#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Block-cooperative channel-min reduction: one block per output pixel.
// Each thread handles one channel (or more if blockDim.x < C).
__global__ void fused_scale_min_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    const int N, const int C, const int H, const int W,
    const float scale_factor
) {
    const int pixel_idx = blockIdx.x;
    if (pixel_idx >= N * H * W) return;

    const int spatial_size = H * W;
    const int n  = pixel_idx / spatial_size;
    const int hw = pixel_idx % spatial_size;

    // Base pointer: NCHW layout, step by H*W between channels for this pixel.
    const float* base = input + n * C * H * W + hw;

    // Each thread accumulates min over its assigned channels.
    float thread_min = INFINITY;
    for (int c = threadIdx.x; c < C; c += blockDim.x) {
        float val = base[c * spatial_size] * scale_factor;
        thread_min = fminf(thread_min, val);
    }

    // Intra-warp min reduction via shuffle.
    unsigned mask = 0xffffffffu;
    for (int offset = 16; offset > 0; offset >>= 1) {
        float other = __shfl_down_sync(mask, thread_min, offset);
        thread_min = fminf(thread_min, other);
    }

    // Cross-warp reduction via shared memory.
    extern __shared__ float smem[];
    const int warp_id  = threadIdx.x >> 5;
    const int lane_id  = threadIdx.x & 31;
    const int num_warps = (blockDim.x + 31) >> 5;

    if (lane_id == 0) {
        smem[warp_id] = thread_min;
    }
    __syncthreads();

    // First warp reduces the per-warp results.
    float final_min = (threadIdx.x < num_warps) ? smem[threadIdx.x] : INFINITY;
    if (threadIdx.x < 32) {
        for (int offset = 16; offset > 0; offset >>= 1) {
            float other = __shfl_down_sync(mask, final_min, offset);
            final_min = fminf(final_min, other);
        }
        if (threadIdx.x == 0) {
            output[pixel_idx] = final_min;
        }
    }
