    const int C = input.size(1);
    const int H = input.size(2);
    const int W = input.size(3);

    auto output = torch::empty({N, 1, H, W}, input.options());

    const int total_pixels = N * H * W;

    // Choose thread count: next power of 2 >= C, clamped to 256.
    int threads = 32;
    while (threads < C && threads < 256) threads <<= 1;
    if (threads > 256) threads = 256;

    const int num_warps = (threads + 31) / 32;
    const size_t smem_bytes = num_warps * sizeof(float);

    fused_scale_min_kernel<<<total_pixels, threads, smem_bytes>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C, H, W,
        scale_factor
